<span class="line">    <span class="token keyword">def</span> <span class="token function">lowestCommonAncestor</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> root<span class="token punctuation">:</span> <span class="token string">&#39;TreeNode&#39;</span><span class="token punctuation">,</span> p<span class="token punctuation">:</span> <span class="token string">&#39;TreeNode&#39;</span><span class="token punctuation">,</span> q<span class="token punctuation">:</span> <span class="token string">&#39;TreeNode&#39;</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token string">&#39;TreeNode&#39;</span><span class="token punctuation">:</span></span>
